import { look, own, person, type HeroStory } from './kit';

// Wren, "The Pack". A hunter raised by Hunter Garrick and by a wolf pack. The night the star fell, the shadow took the
// pack and ran them east; only young Fenn stayed. Moonfang, the pack's mother, pulled the worst of the shadow into
// herself and ran ahead of it, so it would follow her and not her pups.
//
// Umbra's shadow wears the shape of what each hero fears most, and Wren fears the wild turning on her, and the people
// turning on the wild. Meadow: the villages blame the wolves for what Gorehide, the Boar King, does. Woods: Shadowmane,
// the shadow itself in a wolf's coat, leads the pack, and Wren finds Moonfang's hidden pup. Summit: Skyhorn, the stag who
// guards the Cradle, herds every wild thing to the Rift because the shadow took his fawn. Ember: Moonfang's trail through
// the wastes, the Duneworm that hunts her, and Umbra, the Moon-Eater. Across the four lands, people learn the wolves
// were never the dark, and Wren learns to stand between both.

const q = own('wren');

const BURR = person('Burr the Poacher', '🪤', { robe: '#5a5a3a', hat: 'cap', hatColor: '#3a3a24', beard: true });
const BURR_LOOK = look('#5a5a3a', 'cap', { hatColor: '#3a3a24', beard: true });
const wolf = (name: string, fur: string) => person(name, '🐺', { robe: fur, hair: fur });
const FAWN = person('Frostling', '🦌', { robe: '#f4efe6', hat: 'ears', hatColor: '#e8e2d0', skin: '#e8dcc8', hair: '#e8e2d0', small: true });

