    woods: ['m1', 'wren3', 'wren4', 'wren13', 'm3', 'm7', 'm6', 'wren14', 'm9', 'm10', 'm12', 'wren16', 'm11', 'wren19', 'm4', 'm15', 'wren18', 'm17'],
    summit: ['m1', 'm6', 'wren5', 'wren20', 'wren21', 'm10', 'wren25', 'm12', 'wren24', 'wren22', 'm15', 'wren23', 'm19', 'm20'],
    ember: ['m1', 'm2', 'm6', 'm3', 'm4', 'm14', 'wren33', 'm8', 'wren28', 'm7', 'wren29', 'm10', 'wren6', 'wren30', 'wren32', 'm15', 'm12', 'm13'],
